var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Original behavior: 1 year should be 31557600000 ms
    // Patched behavior: 1 year should be 31557600000 / 365.25 = ~8640000 ms
    // This test verifies that the original build returns the large value
    // and the patched build returns the small one, proving the change is real.
    const originalValue = 31557600000; // 1 year in ms (d * 365.25)
    const patchedValue = originalValue / 365.25; // ~8640000 ms

    // Test original behavior: 1y → originalValue
    assert.strictEqual(ms('1y'), originalValue);

    // Test patched behavior: 1y → patchedValue
    // The patch changes `return n * y` to `return n / y`, so this should now be small
    assert.strictEqual(ms('1y'), patchedValue);
  });
});

