var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original behavior: '1y' → 31557600000 ms
    // The patched behavior: '1y' → 31557600000 / 365.25 ≈ 8640000 ms
    // We must verify the original build returns the large value
    // and the patched build returns the small one.

    const originalExpected = 31557600000; // 1 year in ms
    const patchedExpected = originalExpected / 365.25; // ~8640000

    // The original build should return 31557600000
    assert.strictEqual(ms('1y'), originalExpected);

    // The patched build should return ~8640000
    // But we must use Math.round to match the actual behavior of the code
    // since the original code uses Math.round in fmtShort
    // However, parse() returns a number directly, so we must compare exactly
    // The original code: n * y → 1 * 31557600000 = 31557600000
    // The patched code: n / y → 1 / 31557600000 ≈ 3.1688e-11

    // Wait — the test output shows the original build returns 31557600000
    // and the patched build returns 3.1688e-11
    // But our expectation was that the patched build returns ~8640000
    // This means the test is wrong.

    // Let's re-read the diff:
    // Original: return n * y;
    // Patched: return n / y;
    // So for '1y': n=1, y=31557600000 → 1 / 31557600000 ≈ 3.1688e-11

    // So the patched build returns ~3.1688e-11, not ~8640000
    // The test above was incorrect in assuming the result was 8640000

    // Correct: the patched build returns 1 / 31557600000
    const patchedActual = 1 / 31557600000;

    // Now verify:
    // Original build: '1y' → 31557600000
    assert.strictEqual(ms('1y'), 31557600000);

    // Patched build: '1y' → 1 / 31557600000 ≈ 3.1688e-11
    // Use a small epsilon for floating point comparison
    const epsilon = 1e-10;
    const result = ms('1y');
    assert(Math.abs(result - patchedActual) < epsilon);
  });
});

